import os
import sys

import pytest

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'merkle'))

import client
import common
import store


def make_client(n=0):
    s = store.Store()
    c = client.Client(s)
    for i in range(n):
        c.insert(b'k%d' % i, b'v%d' % i)
    return s, c


def test_lookup_absent_in_empty_store():
    s = store.Store()
    c = client.Client(s)
    assert c.lookup(b'anything') is None


def test_lookup_present_key():
    s, c = make_client(1)
    assert c.lookup(b'k0') == b'v0'


def test_lookup_absent_key_returns_none():
    s, c = make_client(10)
    assert c.lookup(b'absent') is None


def test_lookup_many():
    s, c = make_client(100)
    for i in range(100):
        assert c.lookup(b'k%d' % i) == b'v%d' % i


def test_lookup_after_overwrite():
    s, c = make_client(1)
    c.insert(b'k0', b'newvalue')
    assert c.lookup(b'k0') == b'newvalue'


class ForgedProofStore:
    """Store that tampers with proofs."""
    def __init__(self, s, mode):
        self._s = s
        self._mode = mode

    def lookup(self, key):
        p = self._s.lookup(key)
        if self._mode == 'sibling':
            sibs = list(p.siblings)
            if sibs:
                sibs[0] = bytes([sibs[0][0] ^ 1]) + sibs[0][1:]
            else:
                sibs = [common.H(b'fake')]
            return common.Proof(p.key, p.val, sibs)
        if self._mode == 'val':
            return common.Proof(p.key, b'forged', p.siblings)
        if self._mode == 'key':
            return common.Proof(b'fakekey', p.val, p.siblings)

    def insert(self, key, val):
        return self._s.insert(key, val)

    def reset(self):
        self._s.reset()


def test_validate_rejects_wrong_root():
    s, c = make_client(5)
    p = s.lookup(b'k0')
    c2 = client.Client(s, common.H(b'wrongroot'))
    with pytest.raises(Exception, match="Root hash mismatch"):
        c2.validate(b'k0', p)


def test_lookup_rejects_tampered_sibling():
    s, c = make_client(10)
    c._store = ForgedProofStore(s, 'sibling')
    with pytest.raises(Exception, match="Root hash mismatch"):
        c.lookup(b'k0')


def test_lookup_rejects_tampered_value():
    s, c = make_client(10)
    c._store = ForgedProofStore(s, 'val')
    with pytest.raises(Exception, match="Root hash mismatch"):
        c.lookup(b'k0')


def test_validate_asserts_on_bad_proof_types():
    s, c = make_client(1)
    with pytest.raises(AssertionError):
        c.validate(b'k0', "not a proof")
    with pytest.raises(AssertionError):
        c.validate(b'k0', common.Proof('str-key', b'v', []))
    with pytest.raises(AssertionError):
        c.validate(b'k0', common.Proof(b'k', b'v', ['str-sibling']))


def test_reset():
    s, c = make_client(3)
    c.reset()
    assert c._root_hash == common.H_empty()
    assert c.lookup(b'k0') is None

